const arr = $json.orcamento || [];
const brl = v => 'R$ ' + Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const linhas = [];
for (const o of arr) {
  const g = Number(o.gasto||0), lim = Number(o.teto||0), pct = lim>0 ? (g/lim*100) : 0;
  if (pct >= 80) {
    const emoji = pct >= 100 ? '🔴' : '🟡';
    const rest = lim - g;
    linhas.push(`${emoji} *${o.emoji||''} ${o.item}*: ${brl(g)} / ${brl(lim)} (${pct.toFixed(0)}%) — ${rest>=0 ? 'resta '+brl(rest) : 'estourou '+brl(-rest)}`);
  }
}
if (!linhas.length) return [];
const texto = `📊 *Orçamento do mês (até hoje)*\n\n${linhas.join('\n')}\n\n_Aviso ao atingir 80% do teto._`;
return [{ json: { text: texto } }];
